mapper.select:
select c.belong_id archiveId, a.id typeId, b.template_id templateId, b.id groupId, b.group_name groupName, a.type_name typeName, c.id fileId, b.sort, c.filename fileName from (select * from materials_list where business_type = "ARCHIVES") c left join archive_file_type a on c.materials_type = CAST(a.id AS CHAR) left join archive_type_group b on a.group_id = b.id
and (b.group_name LIKE concat('%', #{fileType},'%') or a.type_name LIKE concat('%', #{fileType},'%')) and b.template_id in
#{item}

select c.belong_id archiveId, a.id typeId, b.template_id templateId, b.id groupId, b.group_name groupName, a.type_name typeName, c.id fileId, b.sort, c.filename fileName, c.create_by uploadUser, c.create_time uploadTime from (select * from materials_list where business_type = "ARCHIVES" and belong_id = #{archiveId}) c left join archive_file_type a on c.materials_type = CAST(a.id AS CHAR) left join archive_type_group b on a.group_id = b.id
and (b.group_name LIKE concat('%', #{content},'%') or a.type_name LIKE concat('%', #{content},'%') or c.filename LIKE concat('%', #{content},'%')) and b.group_name = #{groupName}
order by b.sort,a.sort asc
